{
  "name": "opencode-better-file-upload",
  "version": "0.2.1",
  "description": "OpenCode plugin that makes dragging any file (PDF, Word, PowerPoint, Excel, …) into chat just work — even on models that can't read binary documents.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "markitdown",
    "pdf",
    "docx",
    "pptx",
    "file-upload",
    "attachments"
  ],
  "license": "MIT",
  "type": "module",
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./package.json": "./package.json"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "prepublishOnly": "npm run build"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.14"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.14.41",
    "bun-types": "^1.3.14",
    "typescript": "^5.6.0"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/brikerman/opencode-better-file-upload.git"
  },
  "homepage": "https://github.com/brikerman/opencode-better-file-upload#readme",
  "bugs": {
    "url": "https://github.com/brikerman/opencode-better-file-upload/issues"
  }
}
